 thorne:['Commodore Silas Thorne','Royal Navy, West Indies Squadron','#1d2f5a','🎖️'],isa:['Isabel Duarte','Smuggler of the Cove','#6b2a4a','🗝️'],
 kes:['Kestrel Morrow','Captain of the Red Hawk','#8e3a1a','🦅'],ashe:['Brother Ashe','Bell-priest of Saltgrave','#3d4a44','🔔'],
