const SQI={};SQ.forEach((q,i)=>SQI[q.id]=i);
FTYPES.corsair={name:'Corsair',icon:'🏴‍☠️',hp:320,cannons:5,dmg:14,spd:1.18,cost:0,wage:14,len:58,wid:19};
