FTYPES.ironside={name:'Ironside',icon:'⚙️',hp:700,cannons:6,dmg:20,spd:0.98,cost:0,wage:22,len:66,wid:24};
const SSHIP={corsair:'Gull\'s Revenge',wraith:'Lantern Wraith',ironside:'Ironside'};
COS.sail.push(['tattered','Tattered Black',999,'#2a2622'],['fishnet','Fisher\'s Patch',999,'#cbbd98'],['bellshroud','Bell Shroud',999,'#5d6a63'],['abyss','Abyssal Weave',999,'#1c2430']);
COS.flag.push(['republic','Republic Colours',999,'#3a2a12','#e3c97c'],['lastlight','Last Light',999,'#20262c','#ffd27a'],['blacktide','The Black Tide',999,'#050505','#9fd3c7'],['fang','Golden Fang',999,'#6a5a14','#ffe9a0'],['bell','Drowned Bell',999,'#2e3d3a','#c9d7cf']);
COS.hull.push(['forged','Kraken Steel',999,'#33373b','#6b7177'],['gullsteel','Gull Steel',999,'#2f5a52','#8fb8ae']);

function stDef(){return{ch:0,on:0,st:0,n:0,wait:0,day:-1,f:{},side:{},sa:[],pend:[],met:{},done:0,seen:-1};}
function storyMigrate(d){const def=stDef(),o=(d&&d.story&&typeof d.story==='object')?d.story:{};S.story=Object.assign(def,o);const s=S.story;
 s.ch=clamp(s.ch|0,0,CH.length);s.st=Math.max(0,s.st|0);s.n=Math.max(0,s.n|0);s.on=s.on?1:0;s.wait=+s.wait||0;if(s.wait>Date.now()+48*3600e3)s.wait=Date.now()+12*3600e3;
 for(const k of ['f','side','met'])if(!s[k]||typeof s[k]!=='object'||Array.isArray(s[k]))s[k]={};
 s.sa=(Array.isArray(s.sa)?s.sa:[]).filter(id=>SQI[id]!=null&&s.side[id]&&!s.side[id].done).slice(0,3);if(!Array.isArray(s.pend))s.pend=[];s.pend=s.pend.filter(k=>FTYPES[k]);
 for(const id in s.side){if(SQI[id]==null){delete s.side[id];continue;}const q=s.side[id];if(!q||typeof q!=='object'){delete s.side[id];continue;}q.st=Math.max(0,q.st|0);q.n=Math.max(0,q.n|0);q.done=q.done?1:0;}}
const sEns=()=>{if(!S.story)storyMigrate({});return S.story;};
const sDayNow=()=>Math.floor((S.playTime||0)/600);
// ---- locations ----
const portBy=nm=>{const i=PORTS.findIndex(p=>p.name===nm);return i;};
const LOCC={};
function sLoc(a){if(!a)return null;if(LOCC[a])return LOCC[a];const p=a.split(':');let r=null;
 if(p[0]==='P'){const i=portBy(p[1]);if(i>=0)r={x:PORTS[i].port.x,y:PORTS[i].port.y,nm:PORTS[i].name,pi:i};}
 else if(p[0]==='NP'){const i=portBy(p[1]);if(i>=0){const a2=+p[2],d=+p[3];const q=waterNearFixed(PORTS[i].port.x+Math.cos(a2)*d,PORTS[i].port.y+Math.sin(a2)*d);r={x:q.x,y:q.y,nm:'waters off '+PORTS[i].name};}}
 else if(p[0]==='L'){const R=SREGP&&SREGP.find(R=>R.id===p[1]);const l=R&&R.lm[+p[2]];if(l){if(p[3]){const a2=Math.atan2(R.cy-l.y,R.cx-l.x)+Math.PI*0.5;const q=waterNearFixed(l.x+Math.cos(a2)*(l.r*1.3+380),l.y+Math.sin(a2)*(l.r*1.3+380));r={x:q.x,y:q.y,nm:'off '+l.name};}else r={x:l.x,y:l.y,nm:l.name,isl:l.r};}}
 else if(p[0]==='EB'){const q=ebPt(p[1]);if(q)r={x:q.x,y:q.y,nm:EBOSS[p[1]].name};}
 else if(p[0]==='F'){const f=FORTS[+p[1]];if(f){const q=waterNearFixed(f.x+Math.cos(f.a||0)*(+p[2]||900),f.y+Math.sin(f.a||0)*(+p[2]||900));r={x:q.x,y:q.y,nm:'waters off '+f.name};}}
 if(r)LOCC[a]=r;return r;}
// ---- chapter/steps helpers ----
function fOk(c){if(!c)return true;const [k,v]=c.split('=');return(S.story.f[k]||'')===v;}
function chSteps(c){if(c.alt)for(const k in c.alt)if(fOk(k))return c.alt[k];return c.s;}
function lineOk(l){const w=l[0];if(w.includes('|')){const [c,who]=w.split('|');return fOk(c)?[who,l[1]]:null;}return l;}
const KN={navy:'Navy',pirate:'pirate',clan:'clan',merchant:'merchant'};
function sinkDesc(f,n){const parts=[];if(f.vet)parts.push('veteran/elite');if(f.cls)parts.push(CLS[f.cls].n.toLowerCase()+(n>1?'s':''));else if(f.kind==='clan'&&f.clan!=null)parts.push(CLANS[f.clan].short+' ship'+(n>1?'s':''));else parts.push((f.kind?KN[f.kind]+' ':'')+'ship'+(n>1?'s':''));
 if(f.reg){const R=SREGP.find(R=>R.id===f.reg);parts.push('in '+(R?R.name:f.reg));}if(f.far)parts.push('in outer waters');return parts.join(' ');}
function stepTxt(s){switch(s.k){case'dock':return`Dock at ${s.p}`;case'go':{const l=sLoc(s.at);return`Sail to ${l?l.nm:'the mark'}`;}case'sink':return`Sink ${s.n} ${sinkDesc(s.f||{},s.n)}`;
 case'boss':{const l=sLoc(s.at);return`Find and sink ${s.nm}${l?' ('+l.nm+')':''}`;}case'legend':{const L=LEGENDS[LEGI[s.id]];return`Bring down ${L.name} (📜 bounty board at any haven)`;}
 case'fort':return`Capture ${s.n} fort${s.n>1?'s':''}`;case'own':return`Hold ${s.n} forts at once (${ownedForts()}/${s.n})`;case'mat':return`Hand over ${matTxt(s.m,true)} at any haven`;case'gold':return`Pay ${s.n}💰 at any haven`;
 case'frag':return`Hold ${s.n} chart fragment${s.n>1?'s':''} (${Math.min(s.n,S.tr.frag|0)}/${s.n})`;case'grand':return'Dig up the Lost Hoard (❌ on your map)';case'eboss':return`Defeat ${EBOSS[s.id].name} (Lv${EBOSS[s.id].need}+, 2+ fleet ships)`;case'mega':return`Slay ${s.n} Megalodon`;}return'';}
// ---- progress objects: main = {S.story.st,n}, side = S.story.side[id] ----
function curMain(){const s=sEns(),c=CH[s.ch];if(!c||!s.on)return null;const st=chSteps(c)[s.st];return st?{c,st,o:s,key:'m'+s.ch}:null;}
function actives(){const s=sEns(),out=[];const m=curMain();if(m)out.push(m);for(const id of s.sa){const q=SQ[SQI[id]],o=s.side[id];const st=q&&o&&q.s[o.st];if(st)out.push({q,st,o,key:'s'+id});}return out;}
function sAdvance(a){const o=a.o;o.st++;o.n=0;chime();
 if(a.c){const steps=chSteps(a.c);if(o.st>=steps.length){chFinish();return;}toast(`📖 ${a.c.t}: ${stepTxt(steps[o.st])}`);}
 else{if(o.st>=a.q.s.length){sideFinish(a.q);return;}toast(`🍺 ${a.q.t}: ${stepTxt(a.q.s[o.st])}`);}save();}
function sBump(a,need){a.o.n++;if(a.o.n>=need)sAdvance(a);else toast(`${a.c?'📖':'🍺'} ${stepTxt(a.st)} — ${a.o.n}/${need}`);}
function grant(r,src){if(!r)return'';const out=[];if(r.g){S.gold+=r.g;S.earned+=r.g;out.push(r.g+'💰');}if(r.xp){grantXP(r.xp);out.push(r.xp+' XP');}
 if(r.m)for(const k in r.m){S.mat[k]=matN(k)+r.m[k];S.matTot=(S.matTot|0)+r.m[k];out.push(`${r.m[k]}${MATS[k][0]}`);}
 if(r.frag){const before=S.tr.frag|0;fragGain(r.frag,src||'');if((S.tr.frag|0)>before)out.push('🗺️ chart fragment');}
 if(r.cos){S.cosU[r.cos]=1;const [cat,id]=r.cos.split(':');const it=COS[cat].find(x=>x[0]===id);out.push('🎨 '+(it?it[1]:id));}
 if(r.off){const o=OFFICERS.find(x=>x[0]===r.off);if(S.off[r.off]){S.gold+=1500;out.push('1500💰 (officer already aboard)');}else{S.off[r.off]=1;recalc();out.push((o?o[1]+' '+o[2]:'officer')+' joins');}}
 if(r.ship){if(S.fleet.length<4){addShip(r.ship);out.push('⛵ '+SSHIP[r.ship]);}else{S.story.pend.push(r.ship);out.push('⛵ '+SSHIP[r.ship]+' (claim in 📜 Journal when a fleet slot is free)');}}
 if(r.rep)addRep(r.rep[0],r.rep[1],true);return out.join(', ');}
function addShip(k){const t=FTYPES[k];const d={id:S.fid=(S.fid||1)+1,name:SSHIP[k],type:k,lvl:10,maxHp:t.hp,hp:t.hp,cannons:t.cannons,dmg:t.dmg,wage:t.wage,unpaid:0};S.fleet.push(d);if(typeof syncFleet==='function')syncFleet();}
function chFinish(){const s=S.story,c=CH[s.ch];s.on=0;s.st=0;s.n=0;const rw=grant(c.r,'in Act '+c.a);const last=s.ch===CH.length-1;
 const outro=(c.e||[]).map(lineOk).filter(Boolean);s.ch++;const nx=CH[s.ch];
 if(nx){s.wait=nx.wait?Date.now()+nx.wait*3600e3:0;s.day=nx.day?sDayNow()+1:-1;}else s.done=1;
 storySay(outro.concat([['n',`<b>Chapter complete: ${c.t}</b><br>Reward: ${rw||'—'}${nx&&nx.a!==c.a?`<br><br>🏁 <b>Act ${c.a} complete.</b> Act ${nx.a} — ${ACTS[nx.a]} — opens ${nx.wait?'in '+nx.wait+' hours':'soon'}.`:''}${last?'<br><br>🏆 <b>The saga is complete.</b>':''}`]]),{chap:`Act ${c.a} • Chapter ${s.ch}`});
 storyEv('chap',{});save();}
function sideFinish(q){const s=S.story,o=s.side[q.id];o.done=1;s.sa=s.sa.filter(x=>x!==q.id);const rw=grant(q.r,'from '+SPK[q.w][0]);s.met[q.w]=1;
 storySay([[q.w,q.e],['n',`<b>Side quest complete: ${q.t}</b><br>Reward: ${rw}`]],{chap:'Side quest'});save();}
function chAvail(){const s=sEns(),c=CH[s.ch];if(!c||s.on)return null;const why=[];if(S.clvl<c.lvl)why.push(`captain level ${c.lvl}`);const w=s.wait-Date.now();if(w>0)why.push(`${fmtWait(w)}`);if(s.day>=0&&sDayNow()<s.day)why.push(`next sea-day (${Math.ceil((s.day*600-(S.playTime||0))/60)} min at sea)`);return{c,why};}
function fmtWait(ms){const m=Math.ceil(ms/60000);return m>=60?`${Math.floor(m/60)}h ${m%60}m`:`${m}m`;}
function chBegin(){const s=sEns(),av=chAvail();if(!av||av.why.length)return;const c=av.c;
 const lines=(c.d||[]).map(lineOk).filter(Boolean);s.met[(lines[0]||['n'])[0]]=1;
 const go=()=>{s.on=1;s.st=0;s.n=0;toast(`📖 ${c.t}: ${stepTxt(chSteps(c)[0])}`);showTip('story');save();if(state==='port'&&curPort>=0)sDockCheck(curPort);};
 storySay(lines,{chap:`Act ${c.a} — ${ACTS[c.a]} • Chapter ${s.ch+1}: ${c.t}`,choice:c.ch,then:go});}
// ---- events from the game ----
function sinkMatch(f,e){if(!f)return true;if(f.kind&&e.kind!==f.kind)return false;if(f.clan!=null&&e.clan!==f.clan)return false;if(f.cls&&e.cls!==f.cls)return false;if(f.vet&&!(e.vet||e.elite))return false;
 if(f.reg){const R=regionAt(e.x,e.y);if(!R||R.id!==f.reg)return false;}if(f.far&&!(havenDist(e.x,e.y)>5200||regionAt(e.x,e.y)))return false;return true;}
function storyEv(type,data){if(!S.story)return;
 for(const a of actives()){const st=a.st;
  if(type==='sink'){const e=data.e;if(!e||e.tut)continue;if(st.k==='boss'&&e.sq===a.key+':'+a.o.st){for(const o of enemies)if(o.sqe===e.sq)o.keep=false;sAdvance(a);continue;}
   if(st.k==='sink'&&e.kind!=='boss'&&!e.sq&&sinkMatch(st.f,e))sBump(a,st.n);}
  else if(type==='fort'&&st.k==='fort')sBump(a,st.n);else if(type==='mega'&&st.k==='mega')sBump(a,st.n);}}
function stateDone(st){switch(st.k){case'legend':return!!S.lb.done[st.id];case'own':return ownedForts()>=st.n;case'frag':return(S.tr.frag|0)>=st.n;case'grand':return!!S.tr.dug;case'eboss':return!!S.eb[st.id].done;}return false;}
let sT=0,sNag=0;
function storyTick(){const s=sEns();sT++;
 for(const a of actives()){const st=a.st;if(stateDone(st)){sAdvance(a);return;}
  if(st.k==='go'){const l=sLoc(st.at);if(l&&Math.hypot(l.x-P.x,l.y-P.y)<(st.r||(l.isl?l.isl*1.3+420:320))){sAdvance(a);return;}}
  if(st.k==='boss')bossTick(a);}
 const av=chAvail();if(av&&!av.why.length&&!T.on&&S.tutDone&&s.seen!==s.ch&&state==='play'){s.seen=s.ch;toast(`📖 New chapter: "${av.c.t}" — open ☰ ➜ 📜 Journal to begin.`);}}
function bossTick(a){const st=a.st,key=a.key+':'+a.o.st,l=sLoc(st.at);if(!l)return;const d=Math.hypot(l.x-P.x,l.y-P.y);const e=enemies.find(o=>o.sq===key&&!o.sinking);
 if(e){if(d>5600){a.o.hp=e.hp/e.maxHp;enemies.splice(enemies.indexOf(e),1);for(const o of enemies)if(o.sqe===key)o.keep=false;}return;}
 if(d<2400&&!P.dead){const lv=st.lvl||clamp(lvlAt(l.x,l.y)+1,4,14);const o=makeEnemy('boss',l.x,l.y,lv,{sq:key,keep:true,angry:true,aggro:1500,name:st.nm,clan:st.clan,forceCls:st.cls,maxHp:st.hp,legC:st.clan!=null?CLANS[st.clan].sail:st.kind==='navy'?'#e6e1d3':st.kind==='pirate'?'#2a2622':'#8c1c26',ghost:st.ghost?1:0,len:st.cls==='galleon'?84:st.cls==='iron'?78:66,wid:st.cls==='galleon'?28:24,home:{x:l.x,y:l.y}});
  if(a.o.hp>0&&a.o.hp<1)o.hp=Math.max(0.25,a.o.hp)*o.maxHp;enemies.push(o);
  for(let i=0;i<(st.esc|0);i++){const w=waterNear(l.x,l.y,200,380);enemies.push(makeEnemy(st.kind==='clan'?'clan':st.kind==='pirate'?'pirate':'navy',w.x,w.y,Math.max(1,lv-1),{sqe:key,keep:true,angry:true,clan:st.clan,forceCls:'frigate',home:{x:l.x,y:l.y}}));}
  toast(`⚔️ ${st.nm} sighted!`);}}
// docked: dock steps, and hand-overs are explicit buttons
function sDockCheck(pi){for(const a of actives()){const st=a.st;if(st.k==='dock'&&PORTS[pi].name===st.p){sAdvance(a);return sDockCheck(pi);}}}
function storyTargets(out){if(!S.story)return;for(const a of actives()){const st=a.st;let l=null;if(st.k==='dock')l=sLoc('P:'+st.p);else if(st.k==='go'||st.k==='boss')l=sLoc(st.at);if(l)out.push({x:l.x,y:l.y,icon:a.c?'📖':'❗',c:a.c?'#e8c66a':'#9fd3c7'});}}
function storyAct(){const s=S.story;if(!s)return 1;const c=CH[s.ch];return c?c.a:7;}
// ---- port: tavern (side quests) and hand-overs ----
function sideAvail(pi){const s=sEns(),p=PORTS[pi];return SQ.filter(q=>q.p===p.name&&!(s.side[q.id]&&(s.side[q.id].done||s.sa.includes(q.id)))&&(!q.pre||(s.side[q.pre]&&s.side[q.pre].done)));}
function storyPortHTML(p){const pi=PORTS.indexOf(p);sEns();sDockCheck(pi);const s=S.story;let h='';
 const av=chAvail();if(av&&!av.why.length)h+=row(`📖 Story — Chapter ${s.ch+1}: ${av.c.t}`,`Act ${av.c.a}: ${ACTS[av.c.a]}`,btn('sbegin','▶ Begin',true));
 const hand=actives().filter(a=>(a.st.k==='mat'||a.st.k==='gold'));if(hand.length&&p.haven)for(const a of hand){const ok=a.st.k==='mat'?matOk(a.st.m):S.gold>=a.st.n;h+=row(`${a.c?'📖':'🍺'} ${a.c?a.c.t:a.q.t}`,stepTxt(a.st),btn('sgive',a.st.k==='gold'?`Pay ${a.st.n}💰`:'Hand over',ok,a.key));}
 const sq=sideAvail(pi);if(sq.length){h+=`<h3>🍺 Tavern — ${esc(p.name)}</h3><div class="note">Locals with work for a captain. Up to 3 side jobs at once (${s.sa.length}/3).</div>`;
  for(const q of sq){const ok=S.clvl>=q.lvl,sp=SPK[q.w];h+=row(`${sp[3]} ${q.t} <small style="display:inline">Lv${q.lvl}+</small>`,`<i>${esc(sp[0])}:</i> "${q.d}"<br>Reward: ${rwTxt(q.r)}`,btn('stake',ok?(s.sa.length>=3?'Full':'Take'):`Lv${q.lvl}`,ok&&s.sa.length<3,q.id));}}
 return h;}
function rwTxt(r){const o=[];if(r.g)o.push(r.g+'💰');if(r.xp)o.push(r.xp+' XP');if(r.m)o.push(matTxt(r.m,true));if(r.frag)o.push('🗺️ fragment');if(r.cos)o.push('🎨 cosmetic');if(r.off){const x=OFFICERS.find(o=>o[0]===r.off);o.push((x?x[1]+' '+x[2]:'officer'));}if(r.ship)o.push('⛵ '+SSHIP[r.ship]);if(r.rep)o.push('clan rep');return o.join(' • ');}
function storyPortAct(act,arg){if(act==='sbegin'){chBegin();return true;}
 if(act==='stake'){const s=sEns(),q=SQ[SQI[arg]];if(!q||s.sa.length>=3||S.clvl<q.lvl)return true;s.side[q.id]={st:0,n:0,done:0};s.sa.push(q.id);s.met[q.w]=1;
  storySay([[q.w,q.d]],{chap:'Side quest: '+q.t,then:()=>{toast(`🍺 ${q.t}: ${stepTxt(q.s[0])}`);if(curPort>=0)sDockCheck(curPort);if(state==='port')renderPort();}});return true;}
 if(act==='sgive'){if(!PORTS[curPort].haven)return true;const a=actives().find(x=>x.key===arg);if(!a)return true;const st=a.st;
  if(st.k==='mat'&&matOk(st.m)){matPay(st.m);sAdvance(a);}else if(st.k==='gold'&&S.gold>=st.n){S.gold-=st.n;sAdvance(a);}return true;}
 return false;}
// ---- dialogue panel ----
let SQUE=[],sPrev=null,sRetry=0;
function storySay(lines,opt){SQUE.push({lines:lines.slice(),opt:opt||{},i:0});if(SQUE.length===1)sShow();}
function sShow(){const D=SQUE[0];if(!D){sClose();return;}const el=$('story');if(T.on||!['play','port','menu','story'].includes(state)){el.classList.add('hidden');clearTimeout(sRetry);sRetry=setTimeout(sShow,700);return;}if(sPrev==null){sPrev=state;if(state==='play')state='story';}
 el.classList.remove('hidden');const l=D.lines[D.i];const atEnd=D.i>=D.lines.length-1;
 if(!l){sNext();return;}const sp=SPK[l[0]]||SPK.n;const narr=l[0]==='n';
 $('sChap').textContent=D.opt.chap||'';$('sPor').style.setProperty('--c',sp[2]);$('sPor').textContent=sp[3];$('sPor').classList.toggle('narr',narr);
 $('sName').textContent=narr?'':sp[0];$('sRole').textContent=narr?'':sp[1];$('sText').innerHTML=l[1];$('sText').classList.toggle('narr',narr);
 let b='';if(atEnd&&D.opt.choice){const C=D.opt.choice;b=`<div class="sq">${C.q}</div>`+C.o.map((o,i)=>`<button class="sc" data-c="${i}">${o.t}</button>`).join('');}
 else b=`<button data-n="1">${atEnd?'▶ Continue':'Next ›'}</button>`;$('sBtns').innerHTML=b;}
function sNext(){const D=SQUE[0];if(!D)return;D.i++;if(D.i<D.lines.length){sShow();return;}SQUE.shift();if(D.opt.then)D.opt.then();if(SQUE.length)sShow();else sClose();}
function sClose(){$('story').classList.add('hidden');if(sPrev!=null){if(state==='story')state=sPrev==='story'?'play':sPrev;sPrev=null;}if(state==='port'&&curPort>=0)renderPort();if(state==='menu')renderMenu();}
$('sBtns').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const D=SQUE[0];if(!D)return;
 if(b.dataset.c!=null){const o=D.opt.choice.o[+b.dataset.c];S.story.f[o.f]=o.v;save();D.lines.push([D.lines[D.lines.length-1][0],o.say]);D.opt.choice=null;D.i++;sShow();return;}sNext();});
// ---- journal (☰ menu tab) ----
function journalHTML(){const s=sEns();let h='';const c=CH[s.ch];const nDone=s.ch;
 h+=`<div class="note">📜 <b>The Black Tide</b> — a saga in six acts. Chapters ${nDone}/${CH.length} • Side quests ${SQ.filter(q=>s.side[q.id]&&s.side[q.id].done).length}/${SQ.length}</div>`;
 if(s.pend.length)h+=row('⛵ Ships waiting for you',s.pend.map(k=>SSHIP[k]).join(', '),btn('sclaim','Claim',S.fleet.length<4));
 if(!c)h+=row('🏆 The saga is complete',`Ending: ${({burn:'the chart burned',king:'King of the Seas',rep:'the hoard given to the Republic'})[s.f.end]||'—'}`,'');
 else{h+=`<h3>Act ${c.a}: ${ACTS[c.a]}</h3>`;
  if(s.on){const steps=chSteps(c);h+=row(`📖 Chapter ${s.ch+1}: ${c.t}`,steps.map((st,i)=>`${i<s.st?'✅':i===s.st?'▶':'▫️'} ${stepTxt(st)}${i===s.st&&st.k==='sink'?` (${s.n}/${st.n})`:''}${i===s.st&&st.k==='fort'?` (${s.n}/${st.n})`:''}`).join('<br>'),'');}
  else{const av=chAvail();h+=row(`📖 Chapter ${s.ch+1}: ${c.t}`,av.why.length?`🔒 Unlocks with: ${av.why.join(' • ')}`:'Ready to begin.',btn('sbegin','▶ Begin',!av.why.length));}}
 if(s.sa.length){h+=`<h3>🍺 Side quests (${s.sa.length}/3)</h3>`;for(const id of s.sa){const q=SQ[SQI[id]],o=s.side[id];h+=row(`${SPK[q.w][3]} ${q.t}`,q.s.map((st,i)=>`${i<o.st?'✅':i===o.st?'▶':'▫️'} ${stepTxt(st)}${i===o.st&&(st.k==='sink'||st.k==='fort'||st.k==='mega')?` (${o.n}/${st.n})`:''}`).join('<br>')+`<br><small>From ${SPK[q.w][0]}, ${q.p}</small>`,btn('sdrop','Drop',true,id,'red'));}}
 else h+=`<div class="note">🍺 No side quests. Visit a port's ⚓ Dock tab — taverns list local jobs.</div>`;
 h+=`<h3>Acts</h3>`;for(let a=1;a<=6;a++){const chs=CH.map((x,i)=>[x,i]).filter(([x])=>x.a===a);const d=chs.filter(([x,i])=>i<s.ch).length;h+=row(`${d===chs.length?'✅':c&&c.a===a?'▶':'🔒'} Act ${a}: ${ACTS[a]}`,`${d}/${chs.length} chapters • Lv${chs[0][0].lvl}–${chs[chs.length-1][0].lvl}`,'');}
 const fl=[];if(s.f.isa)fl.push(`Isabel: ${s.f.isa}`);if(s.f.kes)fl.push(`Kestrel: ${s.f.kes==='ally'?'partner':'rival'}`);if(s.f.coil)fl.push(`the Coil: ${s.f.coil==='spare'?'spared':'sunk'}`);if(s.f.ashe)fl.push(`Saltgrave: ${s.f.ashe==='bells'?'bells rung':'burned'}`);
 if(fl.length)h+=`<div class="note">⚖️ Your choices: ${fl.join(' • ')}</div>`;
 const met=Object.keys(s.met).filter(k=>SPK[k]&&k!=='n');if(met.length)h+=`<div class="note">👥 People you know: ${met.map(k=>SPK[k][3]+' '+esc(SPK[k][0])).join(' • ')}</div>`;return h;}
function storyMenuAct(a,arg){if(a==='sbegin'){chBegin();return true;}if(a==='sdrop'){const s=sEns();s.sa=s.sa.filter(x=>x!==arg);delete s.side[arg];for(const o of enemies)if(o.sq&&o.sq.startsWith('s'+arg+':'))o.keep=false;toast('🍺 Side quest dropped.');save();return true;}
 if(a==='sclaim'){const s=sEns();while(s.pend.length&&S.fleet.length<4){const k=s.pend.shift();addShip(k);toast(`⛵ ${SSHIP[k]} joins your fleet!`);}save();return true;}return false;}
Object.assign(TIPS,{story:"📖 <b>Story chapter.</b> Objectives show on your map as 📖 (side quests ❗). Track progress in ☰ ➜ 📜 Journal. Some chapters unlock at higher levels or after a rest."});
ACH.push(['act1','📖','The Stolen Page','Finish Act I of the story',()=>(S.story&&S.story.ch>=8)],['act3','🔔','Bells of Saltgrave','Finish Act III of the story',()=>(S.story&&S.story.ch>=26)],
 ['saga','🏴‍☠️','The Black Tide','Finish the whole saga',()=>!!(S.story&&S.story.done)],['side10','🍺','Friend of the Taverns','Finish 10 side quests',()=>S.story&&Object.values(S.story.side).filter(o=>o.done).length>=10],
 ['side30','🍻','Known in Every Port','Finish 30 side quests',()=>S.story&&Object.values(S.story.side).filter(o=>o.done).length>=30]);
